const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2021 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n:host {\n  --override-node-text-label-color: var(--sys-color-token-tag);\n  --override-node-text-class-color: var(--sys-color-token-attribute);\n  --override-node-text-id-color: var(--sys-color-token-attribute);\n  --override-node-text-multiple-descriptors-id: var(--sys-color-on-surface);\n  --override-node-text-multiple-descriptors-class: var(--sys-color-token-property);\n}\n\n.crumbs {\n  display: inline-flex;\n  align-items: stretch;\n  width: 100%;\n  overflow: hidden;\n  pointer-events: auto;\n  cursor: default;\n  white-space: nowrap;\n  position: relative;\n  background: var(--sys-color-cdt-base-container);\n  font-size: inherit;\n  font-family: inherit;\n}\n\n.crumbs-window {\n  flex-grow: 2;\n  overflow: hidden;\n}\n\n.crumbs-scroll-container {\n  display: inline-flex;\n  margin: 0;\n  padding: 0;\n}\n\n.crumb {\n  display: block;\n  padding: 0 7px;\n  line-height: 23px;\n  white-space: nowrap;\n}\n\n.overflow {\n  padding: 0 5px;\n  font-weight: bold;\n  display: block;\n  border: none;\n  flex-grow: 0;\n  flex-shrink: 0;\n  text-align: center;\n  background-color: var(--color-background-elevation-1);\n  color: var(--color-text-secondary);\n  margin: 1px;\n  outline: var(--color-background-elevation-1) solid 1px;\n}\n\n.overflow.hidden {\n  display: none;\n}\n\n.overflow:disabled {\n  opacity: 50%;\n}\n\n.overflow:focus {\n  outline-color: var(--color-primary-old);\n}\n\n.overflow:not(:disabled):hover {\n  background-color: var(--color-background-elevation-2);\n  color: var(--color-text-primary);\n}\n\n.crumb-link {\n  text-decoration: none;\n  color: inherit;\n}\n\n.crumb:hover {\n  background: var(--color-background-elevation-2);\n}\n\n.crumb.selected {\n  background: var(--color-background-elevation-1);\n}\n\n.crumb:focus {\n  outline: var(--color-primary-old) auto 1px;\n}\n\n/*# sourceURL=elementsBreadcrumbs.css */\n");export default styles;